import { FolderPlus, GitBranch, Plus, X } from "lucide-react";
import { useCallback, useMemo, useState } from "react";

import { Sidebar } from "./components/Sidebar";
import { TabBar } from "./components/TabBar";
import { TerminalSplitView } from "./components/TerminalSplitView";
import { WorkspaceHeader } from "./components/WorkspaceHeader";
import { worktreeErrorMessage } from "./lib/ipcErrors";
import { createWorktree, DEFAULT_WORKSPACE_ID, toIpcError } from "./lib/tauri";
import { worktreeIdentity, type Worktree } from "./lib/types";
import { useWorkspaceRuntime } from "./state/workspaceRuntime";
import { useWorkspaceStore } from "./state/workspaceStore";

export function App() {
  const {
    state,
    agents,
    openTab,
    ensureTabForWorktree,
    closeTab,
    enableSplit,
    rotateSplit,
    disableSplit,
    activatePrimary,
    syncWorktrees,
  } = useWorkspaceStore();
  const { runtimeError, refreshWorktrees, reportRuntimeError } = useWorkspaceRuntime({
    activeWorktreePath: state.activeWorktreePath,
    syncWorktrees,
    ensureTabForWorktree,
  });
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [newSlug, setNewSlug] = useState("");
  const [newBaseRef, setNewBaseRef] = useState("HEAD");
  const [createError, setCreateError] = useState<string | null>(null);

  const activeWorktree = useMemo(
    () => state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? null,
    [state.activeWorktreePath, state.worktrees],
  );
  const activeAgent = agents.find((agent) => agent.worktreePath === activeWorktree?.path);

  const handleSelectWorktree = useCallback(
    (worktree: Worktree) => {
      void ensureTabForWorktree(worktree).catch(reportRuntimeError);
    },
    [ensureTabForWorktree, reportRuntimeError],
  );

  const handleCreateWorktreeSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    const slug = newSlug.trim();
    if (!slug || !activeWorktree) return;

    try {
      setCreateError(null);
      await createWorktree({
        workspaceId: DEFAULT_WORKSPACE_ID,
        worktree: { wsId: worktreeIdentity(activeWorktree)?.wsId ?? DEFAULT_WORKSPACE_ID, slug },
        baseRef: newBaseRef || null,
      });
      setIsCreateOpen(false);
      setNewSlug("");
      await refreshWorktrees();
    } catch (error) {
      setCreateError(worktreeErrorMessage(toIpcError(error)));
    }
  };

  const handleAddTerminalTab = () => {
    if (!activeWorktree) return;
    void openTab(activeWorktree).catch(reportRuntimeError);
  };

  const handleCloseTab = (tabId: string) => {
    void closeTab(tabId).catch(reportRuntimeError);
  };

  const handleSplit = () => {
    if (state.layout.split === "none") {
      void enableSplit("horizontal").catch(reportRuntimeError);
    } else if (state.layout.split === "horizontal") {
      rotateSplit();
    } else {
      disableSplit();
    }
  };

  return (
    <div className="flex h-screen w-screen select-none overflow-hidden bg-background font-sans text-foreground">
      <Sidebar
        worktrees={state.worktrees}
        agents={agents}
        activePath={activeWorktree?.path || ""}
        onSelectWorktree={handleSelectWorktree}
        onCreateWorktree={() => {
          setCreateError(null);
          setIsCreateOpen(true);
        }}
      />

      <main className="flex h-full flex-1 flex-col overflow-hidden bg-card">
        {activeWorktree ? (
          <>
            <WorkspaceHeader
              worktree={activeWorktree}
              agent={activeAgent}
              onSplit={handleSplit}
              splitState={state.layout.split}
            />
            <TabBar
              tabs={state.layout.tabs}
              activeTabId={state.layout.primaryTabId ?? ""}
              onActivate={activatePrimary}
              onClose={handleCloseTab}
              onAdd={handleAddTerminalTab}
            />
            <TerminalSplitView layout={state.layout} sessions={state.sessions} />
          </>
        ) : (
          <div className="flex h-full flex-1 items-center justify-center text-xs text-muted-foreground">
            {runtimeError ? `Workspace unavailable (${runtimeError.code})` : "No workspace available"}
          </div>
        )}
      </main>

      {runtimeError && activeWorktree ? (
        <div className="pointer-events-none fixed bottom-3 right-3 z-40 max-w-error rounded-md border border-destructive/30 bg-card/95 px-3 py-2 text-[11px] text-destructive shadow-lg">
          {runtimeError.code}: {runtimeError.message}
        </div>
      ) : null}

      {isCreateOpen ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <form
            onSubmit={handleCreateWorktreeSubmit}
            className="w-96 animate-enter space-y-4 rounded-xl border border-border bg-card p-5 shadow-2xl"
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 text-sm font-semibold">
                <FolderPlus className="size-4 text-primary" />
                <span>Create New Worktree</span>
              </div>
              <button
                type="button"
                onClick={() => setIsCreateOpen(false)}
                className="text-muted-foreground hover:text-foreground"
              >
                <X className="size-4" />
              </button>
            </div>

            <div className="space-y-3 text-xs">
              <div>
                <label className="mb-1 block text-muted-foreground">Branch / Worktree Slug</label>
                <input
                  type="text"
                  autoFocus
                  placeholder="e.g. feature-auth"
                  value={newSlug}
                  onChange={(event) => setNewSlug(event.target.value)}
                  className="w-full rounded-md border border-input bg-background px-3 py-1.5 text-xs text-foreground focus:outline-none focus:ring-1 focus:ring-primary"
                />
              </div>

              <div>
                <label className="mb-1 block text-muted-foreground">Base Ref / Branch</label>
                <div className="flex items-center gap-2 rounded-md border border-input bg-background px-3 py-1.5 text-xs text-foreground">
                  <GitBranch className="size-3.5 text-muted-foreground" />
                  <input
                    type="text"
                    value={newBaseRef}
                    onChange={(event) => setNewBaseRef(event.target.value)}
                    className="flex-1 bg-transparent focus:outline-none"
                  />
                </div>
              </div>
              {createError ? <p className="rounded-md bg-destructive/10 px-2 py-1.5 text-destructive">{createError}</p> : null}
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <button
                type="button"
                onClick={() => setIsCreateOpen(false)}
                className="rounded-md px-3 py-1.5 text-xs text-muted-foreground hover:bg-accent hover:text-foreground"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="flex items-center gap-1.5 rounded-md bg-primary px-3.5 py-1.5 text-xs font-medium text-primary-foreground transition-colors hover:bg-primary/90"
              >
                <Plus className="size-3.5" />
                <span>Create Worktree</span>
              </button>
            </div>
          </form>
        </div>
      ) : null}
    </div>
  );
}

export default App;

import type { LayoutState, Pane, TerminalSession } from "../lib/types";
import { TerminalPane } from "./TerminalPane";

type TerminalSplitViewProps = {
  layout: LayoutState;
  sessions: Record<string, TerminalSession>;
};

export function TerminalSplitView({ layout, sessions }: TerminalSplitViewProps) {
  const primaryTab = layout.tabs.find((tab) => tab.id === layout.primaryTabId) ?? null;
  const secondaryTab = layout.split !== "none"
    ? layout.tabs.find((tab) => tab.id === layout.secondaryTabId) ?? null
    : null;
  const primarySession = primaryTab ? sessions[primaryTab.sessionId] ?? null : null;
  const secondarySession = secondaryTab ? sessions[secondaryTab.sessionId] ?? null : null;
  const primaryPane: Pane | null = primaryTab ? { id: "primary", tabId: primaryTab.id } : null;
  const secondaryPane: Pane | null = secondaryTab ? { id: "secondary", tabId: secondaryTab.id } : null;

  if (!primaryTab || !primaryPane || !primarySession) {
    return <div className="relative flex-1 overflow-hidden bg-terminal" data-testid="terminal-layout" data-split="none" />;
  }

  return (
    <div
      className={`relative flex flex-1 overflow-hidden ${
        layout.split === "horizontal" ? "flex-row" : layout.split === "vertical" ? "flex-col" : ""
      }`}
      data-testid="terminal-layout"
      data-split={layout.split}
    >
      <div className="relative h-full w-full flex-1 overflow-hidden" data-testid="primary-pane" data-pane-id={primaryPane.id}>
        <TerminalPane key={primaryTab.id} session={primarySession} active />
      </div>

      {layout.split !== "none" && secondaryTab && secondaryPane && secondarySession ? (
        <div
          className={`relative h-full w-full flex-1 overflow-hidden ${
            layout.split === "horizontal" ? "border-l border-border" : "border-t border-border"
          }`}
          data-testid="secondary-pane"
          data-pane-id={secondaryPane.id}
        >
          <TerminalPane key={secondaryTab.id} session={secondarySession} active />
        </div>
      ) : null}
    </div>
  );
}

import type { FitAddon } from "@xterm/addon-fit";
import type { Terminal } from "@xterm/xterm";
import { useEffect, useRef, useState } from "react";

import { isTauriRuntime, resizeTerminal, writeTerminal } from "../lib/tauri";
import { terminalEventBus } from "../lib/terminalEvents";
import { attachWebglRenderer, loadTerminalAssets } from "../lib/terminalRenderer";
import type { TerminalSession } from "../lib/types";

type TerminalPaneProps = {
  session: TerminalSession;
  active: boolean;
};

const TERMINAL_THEME = {
  background: "#0a0a0a",
  foreground: "#d4d4d4",
  cursor: "#e5e5e5",
  cursorAccent: "#0a0a0a",
  selectionBackground: "#52525299",
  black: "#171717",
  red: "#f87171",
  green: "#86efac",
  yellow: "#fde68a",
  blue: "#93c5fd",
  magenta: "#d8b4fe",
  cyan: "#67e8f9",
  white: "#e5e5e5",
  brightBlack: "#737373",
  brightRed: "#fca5a5",
  brightGreen: "#bbf7d0",
  brightYellow: "#fef08a",
  brightBlue: "#bfdbfe",
  brightMagenta: "#e9d5ff",
  brightCyan: "#a5f3fc",
  brightWhite: "#fafafa",
} as const;

export function TerminalPane({ session, active }: TerminalPaneProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const terminalRef = useRef<Terminal | null>(null);
  const fitRef = useRef<FitAddon | null>(null);
  const sessionRef = useRef(session);
  const [connectionError, setConnectionError] = useState<string | null>(null);

  sessionRef.current = session;

  useEffect(() => {
    if (active) {
      requestAnimationFrame(() => {
        fitRef.current?.fit();
        terminalRef.current?.focus();
      });
    }
  }, [active]);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;

    const abortController = new AbortController();
    let disposed = false;
    let cleanupTerminal: (() => void) | null = null;
    setConnectionError(null);

    void initialize(host).catch((error: unknown) => {
      if (disposed) return;
      setConnectionError(error instanceof Error ? error.message : "Terminal renderer failed");
    });

    async function initialize(hostElement: HTMLDivElement) {
      const { Terminal: TerminalConstructor, FitAddon: FitAddonConstructor } = await loadTerminalAssets();
      if (disposed) return;

      const terminal = new TerminalConstructor({
        allowProposedApi: false,
        convertEol: true,
        cursorBlink: true,
        cursorStyle: "bar",
        fontFamily: '"SF Mono", SFMono-Regular, ui-monospace, Menlo, monospace',
        fontSize: 13,
        lineHeight: 1.2,
        letterSpacing: 0,
        scrollback: 10_000,
        theme: TERMINAL_THEME,
      });
      const fitAddon = new FitAddonConstructor();
      terminal.loadAddon(fitAddon);
      terminal.open(hostElement);
      terminalRef.current = terminal;
      fitRef.current = fitAddon;

      let disposeWebgl: () => void = () => undefined;
      void attachWebglRenderer(terminal, abortController.signal).then((dispose) => {
        if (disposed) {
          dispose();
          return;
        }
        disposeWebgl = dispose;
      });

      let resizeFrame = 0;
      const resize = () => {
        cancelAnimationFrame(resizeFrame);
        resizeFrame = requestAnimationFrame(() => {
          if (disposed || hostElement.clientWidth === 0 || hostElement.clientHeight === 0) return;
          fitAddon.fit();
          const backendSessionId = sessionRef.current.backendSessionId;
          if (!backendSessionId) return;
          void resizeTerminal({ sessionId: backendSessionId, cols: terminal.cols, rows: terminal.rows }).catch(() => undefined);
        });
      };

      const resizeObserver = new ResizeObserver(resize);
      resizeObserver.observe(hostElement);

      const dataDisposable = terminal.onData((data) => {
        const backendSessionId = sessionRef.current.backendSessionId;
        if (!backendSessionId) return;
        void writeTerminal({ sessionId: backendSessionId, data }).catch((error: unknown) => {
          setConnectionError(error instanceof Error ? error.message : "Terminal write failed");
        });
      });

      const focusTerminal = () => terminal.focus();
      hostElement.addEventListener("pointerdown", focusTerminal);

      const backendSessionId = sessionRef.current.backendSessionId;
      const unsubscribeOutput = backendSessionId
        ? terminalEventBus.subscribeOutput(backendSessionId, (text) => terminal.write(text))
        : () => undefined;

      if (!isTauriRuntime()) {
        terminal.writeln("\x1b[1;32mORCA Lite\x1b[0m  UI preview");
        terminal.writeln("\x1b[90mLaunch through Tauri to attach the PTY session.\x1b[0m");
        terminal.write("\r\n\x1b[34m~\x1b[0m \x1b[32m❯\x1b[0m ");
      }

      resize();
      if (active) terminal.focus();

      cleanupTerminal = () => {
        cancelAnimationFrame(resizeFrame);
        resizeObserver.disconnect();
        hostElement.removeEventListener("pointerdown", focusTerminal);
        dataDisposable.dispose();
        unsubscribeOutput();
        disposeWebgl();
        terminal.dispose();
        terminalRef.current = null;
        fitRef.current = null;
      };
    }

    return () => {
      disposed = true;
      abortController.abort();
      cleanupTerminal?.();
    };
  }, [session.id]);

  return (
    <div className="relative h-full w-full bg-terminal">
      <div ref={hostRef} className="terminal-host h-full w-full" aria-label={`Terminal in ${session.cwd}`} />
      {connectionError ? (
        <div className="pointer-events-none absolute bottom-3 right-3 max-w-error rounded-md border border-destructive/30 bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
          PTY disconnected
        </div>
      ) : null}
    </div>
  );
}

import { Bot, GitBranch, PanelRight, Radio, SplitSquareHorizontal, SplitSquareVertical } from "lucide-react";

import type { ActiveAgent, Worktree } from "../lib/types";
import { IconButton } from "./ui/IconButton";
import { StatusDot } from "./ui/StatusDot";

type WorkspaceHeaderProps = {
  worktree: Worktree;
  agent?: ActiveAgent;
  onSplit?: () => void;
  splitState?: "none" | "horizontal" | "vertical";
};

function branchName(worktree: Worktree) {
  return worktree.branch?.replace(/^refs\/heads\//, "") ?? "detached HEAD";
}

function basename(path: string) {
  if (path === ".") return "main";
  return path.split(/[\\/]/).filter(Boolean).at(-1) ?? path;
}

export function WorkspaceHeader({ worktree, agent, onSplit, splitState = "none" }: WorkspaceHeaderProps) {
  return (
    <header className="drag-region flex h-titlebar shrink-0 items-center border-b border-border bg-sidebar pl-3 pr-2">
      <div className="flex min-w-0 flex-1 items-center gap-2">
        <div className="flex size-6 shrink-0 items-center justify-center rounded-md bg-accent text-muted-foreground">
          <GitBranch className="size-3.5" />
        </div>
        <div className="min-w-0">
          <div className="flex items-center gap-1.5">
            <span className="truncate text-[13px] font-semibold text-foreground">{basename(worktree.path)}</span>
            {agent ? <StatusDot state={agent.state} /> : null}
          </div>
          <div className="truncate font-mono text-[10px] text-muted-foreground">{branchName(worktree)}</div>
        </div>
      </div>

      {agent ? (
        <div className="no-drag mr-2 hidden items-center gap-1.5 rounded-md border border-border bg-card px-2 py-1 text-[11px] text-muted-foreground md:flex">
          <Bot className="size-3" />
          <span className="max-w-agent truncate">{agent.name}</span>
          <Radio className="size-2.5 text-status-working" />
        </div>
      ) : null}

      <div className="no-drag flex items-center gap-0.5">
        <IconButton
          label={`Split terminal (${splitState})`}
          size="sm"
          onClick={onSplit}
          className={splitState !== "none" ? "bg-accent text-foreground" : ""}
        >
          {splitState === "vertical" ? (
            <SplitSquareVertical className="size-3.5" />
          ) : (
            <SplitSquareHorizontal className="size-3.5" />
          )}
        </IconButton>
        <IconButton label="Toggle details" size="sm">
          <PanelRight className="size-3.5" />
        </IconButton>
      </div>
    </header>
  );
}

import type { LayoutState, SplitMode, TerminalTab } from "../lib/types";

export type LayoutAction =
  | { type: "ADD_TAB"; tab: TerminalTab; activate?: boolean }
  | { type: "CLOSE_TAB"; tabId: string; replacementTab?: TerminalTab }
  | { type: "ACTIVATE_PRIMARY"; tabId: string }
  | { type: "ACTIVATE_SECONDARY"; tabId: string }
  | {
      type: "ENABLE_SPLIT";
      orientation: Exclude<SplitMode, "none">;
      secondaryTabId?: string;
      secondaryTab?: TerminalTab;
    }
  | { type: "ROTATE_SPLIT" }
  | { type: "DISABLE_SPLIT" };

export function createLayoutState(tabs: TerminalTab[] = [], primaryTabId?: string | null): LayoutState {
  return normalizeLayout({
    tabs,
    primaryTabId: primaryTabId ?? tabs[0]?.id ?? null,
    secondaryTabId: null,
    split: "none",
  });
}

export function layoutReducer(state: LayoutState, action: LayoutAction): LayoutState {
  switch (action.type) {
    case "ADD_TAB": {
      const tabs = state.tabs.some((tab) => tab.id === action.tab.id) ? state.tabs : [...state.tabs, action.tab];
      return normalizeLayout({
        ...state,
        tabs,
        primaryTabId: action.activate === false ? state.primaryTabId : action.tab.id,
      });
    }
    case "CLOSE_TAB": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return normalizeLayout(state);

      let tabs = state.tabs.filter((tab) => tab.id !== action.tabId);
      if (tabs.length === 0 && action.replacementTab) tabs = [action.replacementTab];

      let primaryTabId = state.primaryTabId === action.tabId ? tabs[0]?.id ?? null : state.primaryTabId;
      if (primaryTabId && !tabs.some((tab) => tab.id === primaryTabId)) primaryTabId = tabs[0]?.id ?? null;

      let secondaryTabId = state.secondaryTabId === action.tabId ? null : state.secondaryTabId;
      if (secondaryTabId && !tabs.some((tab) => tab.id === secondaryTabId)) secondaryTabId = null;

      let split = state.split;
      if (split !== "none") {
        if (!secondaryTabId || secondaryTabId === primaryTabId) {
          secondaryTabId = tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;
        }
        if (!secondaryTabId) split = "none";
      }

      return normalizeLayout({ tabs, primaryTabId, secondaryTabId, split });
    }
    case "ACTIVATE_PRIMARY": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayout({ ...state, primaryTabId: action.tabId });
    }
    case "ACTIVATE_SECONDARY": {
      if (state.split === "none" || !state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayout({ ...state, secondaryTabId: action.tabId });
    }
    case "ENABLE_SPLIT": {
      const tabs = action.secondaryTab && !state.tabs.some((tab) => tab.id === action.secondaryTab?.id)
        ? [...state.tabs, action.secondaryTab]
        : state.tabs;
      const primaryTabId = state.primaryTabId ?? tabs[0]?.id ?? null;
      const requestedSecondaryId = action.secondaryTab?.id ?? action.secondaryTabId ?? null;
      const secondaryTabId =
        requestedSecondaryId && requestedSecondaryId !== primaryTabId && tabs.some((tab) => tab.id === requestedSecondaryId)
          ? requestedSecondaryId
          : tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;

      return normalizeLayout({
        tabs,
        primaryTabId,
        secondaryTabId,
        split: secondaryTabId ? action.orientation : "none",
      });
    }
    case "ROTATE_SPLIT":
      return normalizeLayout({
        ...state,
        split: state.split === "horizontal" ? "vertical" : state.split === "vertical" ? "horizontal" : "none",
      });
    case "DISABLE_SPLIT":
      return normalizeLayout({ ...state, split: "none", secondaryTabId: null });
  }
}

function normalizeLayout(state: LayoutState): LayoutState {
  const tabs = dedupeTabs(state.tabs);
  if (tabs.length === 0) {
    return { tabs: [], primaryTabId: null, secondaryTabId: null, split: "none" };
  }

  const primaryTabId = tabs.some((tab) => tab.id === state.primaryTabId) ? state.primaryTabId : tabs[0].id;
  let split = state.split;
  let secondaryTabId = tabs.some((tab) => tab.id === state.secondaryTabId) ? state.secondaryTabId : null;

  if (secondaryTabId === primaryTabId) {
    secondaryTabId = tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;
  }

  if (split !== "none" && !secondaryTabId) {
    secondaryTabId = tabs.find((tab) => tab.id !== primaryTabId)?.id ?? null;
  }

  if (split !== "none" && !secondaryTabId) split = "none";
  if (split === "none") secondaryTabId = null;

  return { tabs, primaryTabId, secondaryTabId, split };
}

function dedupeTabs(tabs: TerminalTab[]) {
  const seen = new Set<string>();
  return tabs.filter((tab) => {
    if (seen.has(tab.id)) return false;
    seen.add(tab.id);
    return true;
  });
}

import { Plus, TerminalSquare, X } from "lucide-react";

import { cn } from "../lib/cn";
import type { TerminalTab } from "../lib/types";
import { IconButton } from "./ui/IconButton";

type TabBarProps = {
  tabs: TerminalTab[];
  activeTabId: string;
  onActivate: (id: string) => void;
  onClose: (id: string) => void;
  onAdd: () => void;
};

export function TabBar({ tabs, activeTabId, onActivate, onClose, onAdd }: TabBarProps) {
  return (
    <div className="flex h-tabbar shrink-0 items-stretch border-b border-border bg-card pr-1.5">
      <div className="flex min-w-0 flex-1 items-stretch overflow-x-auto scrollbar-none">
        {tabs.map((tab) => {
          const active = tab.id === activeTabId;
          return (
            <button
              key={tab.id}
              type="button"
              onClick={() => onActivate(tab.id)}
              className={cn(
                "group relative flex min-w-tab max-w-tab items-center gap-1.5 border-r border-border px-2 text-xs transition-colors",
                active ? "bg-background text-foreground" : "bg-card text-muted-foreground hover:bg-accent/50 hover:text-foreground",
              )}
            >
              <TerminalSquare className="size-3.5 shrink-0" />
              <span className="min-w-0 flex-1 truncate text-left">{tab.label}</span>
              <span
                role="button"
                tabIndex={0}
                aria-label={`Close ${tab.label}`}
                onClick={(event) => {
                  event.stopPropagation();
                  onClose(tab.id);
                }}
                onKeyDown={(event) => {
                  if (event.key === "Enter" || event.key === " ") {
                    event.stopPropagation();
                    onClose(tab.id);
                  }
                }}
                className="rounded p-0.5 text-muted-foreground opacity-0 hover:bg-muted hover:text-foreground group-hover:opacity-100"
              >
                <X className="size-3" />
              </span>
              {active ? <span className="absolute inset-x-0 bottom-0 h-0.5 bg-foreground" /> : null}
            </button>
          );
        })}
      </div>
      <IconButton label="New terminal" size="sm" className="my-auto ml-1" onClick={onAdd}>
        <Plus className="size-3.5" />
      </IconButton>
    </div>
  );
}

import { Bot, FolderPlus, LayoutDashboard, PanelLeftClose, Search, Settings2, SlidersHorizontal } from "lucide-react";

import type { ActiveAgent, Worktree } from "../lib/types";
import { AgentCards } from "./AgentCards";
import { IconButton } from "./ui/IconButton";
import { SectionHeader } from "./ui/SectionHeader";
import { WorktreeList } from "./WorktreeList";

type SidebarProps = {
  worktrees: Worktree[];
  agents: ActiveAgent[];
  activePath: string;
  onSelectWorktree: (worktree: Worktree) => void;
